export function getCatalogTopicsForExam(subject: string, exam: string): string[] {
  const indices =
    TOPICS_BY_EXAM_SUBJECT[`${exam || "All Exams"}::${subject}`] ??
    TOPICS_BY_EXAM_SUBJECT[`All Exams::${subject}`];
  if (!indices) return [];
  return indices.map((idx) => TOPIC_POOL[idx] ?? "").filter(Boolean);
}

export function getCatalogQuestionCount(subject: string, exam: string): number {
  return (
    COUNT_BY_EXAM_SUBJECT[`${exam || "All Exams"}::${subject}`] ??
    COUNT_BY_EXAM_SUBJECT[`All Exams::${subject}`] ??
    0
  );
}
